/**
 * Story 452: Tailwind on every site. The classes the views use, generated by the
 * server with Tailwind's JavaScript compiler, served at `/css/tailwind.css`
 * behind a hash and linked in every page's head; the site's own input, the
 * setting that turns it off, a save regenerating it, two servers agreeing, a
 * broken input, and the class list the template editor completes from.
 */
import { afterEach, describe, expect, test } from 'bun:test'
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { DEFAULT_BACKOFFICE_PATH } from '@crombolo/core'
import { ComponentRepository, ContentTypeRepository } from '@crombolo/data'
import {
  contentHash,
  hashedAddress,
  splitHashedAddress,
  withPageStylesheet,
} from '@crombolo/render'
import {
  buildAhead,
  type CromboloConfig,
  classCandidates,
  cssColorToHex,
  loadConfig,
  SiteTailwind,
  TAILWIND_PATH,
  type TailwindClassList,
  tailwindProblem,
} from '@crombolo/server'
import { scaffoldFiles } from '../packages/cli/src/templates.ts'
import { type Harness, ORIGIN, signedInServer, V1 } from './support/harness.ts'

const CLASSES = `${DEFAULT_BACKOFFICE_PATH}/crombolo/api/tailwind-classes`

const open: Harness[] = []
const dirs: string[] = []
afterEach(async () => {
  while (open.length > 0)
    await open
      .pop()
      ?.db.close()
      .catch(() => {})
  while (dirs.length > 0) rmSync(dirs.pop() as string, { recursive: true, force: true })
})

const PAGE_TOML = `[content-type]
alias = "page"
name = "Page"
allow-at-root = true
components = ["page"]
default-component = "page"
`

const view = (classes: string, head = '') => `import { asset } from '@crombolo/crombolo'
export default () => (
  <html><head>
    <meta charset="utf-8" />${head}
    <link rel="stylesheet" href={asset('/css/site.css')} />
  </head><body><h1 className="${classes}">Home</h1></body></html>
)
`

function siteFiles(options: { classes?: string; input?: string; head?: string } = {}) {
  const root = mkdtempSync(join(process.cwd(), 'output', 'tailwind-'))
  dirs.push(root)
  for (const dir of ['schema/content-types', 'components', 'css'])
    mkdirSync(join(root, dir), { recursive: true })
  writeFileSync(join(root, 'schema', 'schema.toml'), '[schema]\nversion = "1.0.0"\n')
  writeFileSync(join(root, 'schema', 'content-types', 'page.toml'), PAGE_TOML)
  writeFileSync(
    join(root, 'components', 'page.tsx'),
    view(options.classes ?? 'p-4 text-red-500', options.head),
  )
  writeFileSync(join(root, 'css', 'site.css'), 'h1 { margin: 0 }\n')
  if (options.input !== undefined) writeFileSync(join(root, 'css', 'tailwind.css'), options.input)
  const config: Partial<CromboloConfig> = {
    siteDir: root,
    schemaDir: join(root, 'schema'),
    componentsDir: join(root, 'components'),
    componentsCacheDir: join(root, '.crombolo'),
    stylesheetsDir: join(root, 'css'),
  }
  return { root, config }
}

async function site(
  options: Parameters<typeof siteFiles>[0] & { config?: Partial<CromboloConfig> } = {},
) {
  const files = siteFiles(options)
  const h = await signedInServer({ config: { ...files.config, ...options.config } })
  open.push(h)
  await publishHome(h)
  const visit = (path: string, headers: Record<string, string> = {}) =>
    h.server.fetch(new Request(`${ORIGIN}${path}`, { headers }))
  return { h, root: files.root, visit }
}

async function publishHome(h: Harness) {
  const created = await h.post(`${V1}/document`, {
    documentType: { id: (await new ContentTypeRepository(h.server.db).byAlias('page'))?.key },
    template: { id: (await new ComponentRepository(h.server.db).byAlias('page'))?.key },
    parent: null,
    values: [],
    variants: [{ culture: null, segment: null, name: 'Home' }],
  })
  const key = created.headers.get('umb-generated-resource') as string
  expect((await h.put(`${V1}/document/${key}/publish`, { publishSchedules: [] })).status).toBe(200)
}

/** The stylesheet a page links, and its address. */
async function linked(visit: (path: string) => Promise<Response>) {
  const html = await (await visit('/')).text()
  const address = /href="(\/css\/tailwind\.[0-9a-f]{8}\.css)"/.exec(html)?.[1]
  return { html, address, css: address ? await (await visit(address)).text() : undefined }
}

describe('the classes a view uses', () => {
  test('are candidates, as Tailwind would find them, arbitrary values and variants included', () => {
    const found = classCandidates(
      `<div className="p-4 md:hover:bg-red-500" class={cn('mt-2', open && "block")}>` +
        '{`grid-cols-[1fr_2fr] $' +
        "{x}`} content-['hi'] w-[calc(100%-1rem)]</div>",
    )
    for (const candidate of [
      'p-4',
      'md:hover:bg-red-500',
      'mt-2',
      'block',
      'grid-cols-[1fr_2fr]',
      "content-['hi']",
      'w-[calc(100%-1rem)]',
    ])
      expect(found).toContain(candidate)
    expect(found).toEqual([...found].sort())
  })

  test('include arbitrary variants with brackets inside, and two bracket groups', () => {
    const classes = [
      '[&_[data-field]]:mt-2',
      '[&>[role=status]]:hidden',
      '[&_p[role=alert]]:text-red-600',
      '[&_div:has(input)]:grid-cols-[auto_1fr]',
      'md:[&:nth-of-type(even)>img]:-order-1',
      '[&_input:not([type=checkbox])]:border',
    ]
    const found = classCandidates(`<div className="${classes.join(' ')}"></div>`)
    for (const candidate of classes) expect(found).toContain(candidate)
  })

  test('are styled on the page with no import or build, linked once before the site’s CSS', async () => {
    const { visit } = await site()
    const { html, address, css } = await linked(visit)
    expect(address).toBeDefined()
    expect(html.split('/css/tailwind.').length - 1).toBe(1)
    expect(html.indexOf(address as string)).toBeLessThan(html.indexOf('/css/site.'))
    expect(html.indexOf('<meta charset')).toBeLessThan(html.indexOf(address as string))
    expect(css).toContain('.p-4 {')
    expect(css).toContain('.text-red-500 {')
    // Tailwind's base reset, on by default.
    expect(css).toContain('@layer base')
    expect(contentHash(css as string)).toBe(splitHashedAddress(address as string)?.hash as string)
  })

  test('are kept for a year at the hashed address, asked again at the plain one', async () => {
    const { visit } = await site()
    const { address, css } = await linked(visit)
    const kept = await visit(address as string)
    expect(kept.headers.get('cache-control')).toBe('public, max-age=31536000, immutable')
    expect(kept.headers.get('content-type')).toStartWith('text/css')
    const plain = await visit(TAILWIND_PATH)
    expect(plain.headers.get('cache-control')).toBe('no-cache')
    expect(await plain.text()).toBe(css as string)
    const stale = await visit(hashedAddress(TAILWIND_PATH, '00000000'))
    expect(stale.status).toBe(404)
    expect(stale.headers.get('cache-control')).toBe('no-store')
  })

  test('a view that links the stylesheet itself is not given a second link', async () => {
    const { visit } = await site({
      head: `\n    <link rel="stylesheet" href={asset('/css/tailwind.css')} />`,
    })
    const { html, address } = await linked(visit)
    expect(address).toBeDefined()
    expect(html.split('/css/tailwind.').length - 1).toBe(1)
  })

  test('a class saved in the template editor is styled on the next page load, at a new hash', async () => {
    const { h, visit } = await site()
    const before = await linked(visit)
    expect(before.css).not.toContain('.text-fuchsia-700')
    const key = (await new ComponentRepository(h.server.db).byAlias('page'))?.key
    const saved = await h.put(`${V1}/template/${key}`, {
      name: 'Page',
      alias: 'page',
      content: view('p-4 text-fuchsia-700'),
    })
    expect(saved.status).toBe(200)
    const after = await linked(visit)
    expect(after.address).not.toBe(before.address)
    expect(after.css).toContain('.text-fuchsia-700 {')
    // The one a page rendered just before still answers.
    expect((await visit(before.address as string)).status).toBe(200)
  })

  test('two servers over the same files give the same stylesheet, at the same hash', async () => {
    const files = siteFiles({ classes: 'flex gap-2 bg-sky-600' })
    const hashes: string[] = []
    for (let i = 0; i < 2; i++) {
      const h = await signedInServer({ config: files.config })
      open.push(h)
      const css = await (await h.server.fetch(new Request(`${ORIGIN}${TAILWIND_PATH}`))).text()
      expect(css).toContain('.bg-sky-600 {')
      hashes.push(contentHash(css))
    }
    expect(hashes[0]).toBe(hashes[1] as string)
  })
})

describe('the site’s own css/tailwind.css', () => {
  const INPUT = `@import "tailwindcss";
@theme {
  --color-brand: #ff6600;
}
@source inline("underline italic");
`

  test('replaces the default: a @theme colour is a class, and @source inline generates classes', async () => {
    const { visit } = await site({ classes: 'bg-brand', input: INPUT })
    const { css } = await linked(visit)
    expect(css).toContain('--color-brand: #ff6600')
    expect(css).toContain('.bg-brand {')
    expect(css).toContain('.underline {')
    expect(css).toContain('.italic {')
    // The input is not what is served at its address.
    expect(css).not.toContain('@import')
  })

  test('names a plugin the CMS ships, which a site with no modules of its own still gets', async () => {
    const { root, config } = siteFiles({
      classes: 'prose prose-lg',
      input: '@import "tailwindcss";\n@plugin "@tailwindcss/typography";\n',
    })
    const tailwind = new SiteTailwind({
      siteDir: root,
      componentsDir: config.componentsDir as string,
      stylesheetsDir: config.stylesheetsDir as string,
    })
    await tailwind.refresh()
    const css = tailwind.current()?.css ?? ''
    expect(css).toContain('.prose {')
    expect(css).toContain('.prose-lg {')
  })

  test('that does not compile is said with its line, and the last good stylesheet stays', async () => {
    const { root, config } = siteFiles({ classes: 'bg-brand', input: INPUT })
    const problems: unknown[] = []
    const tailwind = new SiteTailwind({
      siteDir: root,
      componentsDir: config.componentsDir as string,
      stylesheetsDir: config.stylesheetsDir as string,
      onProblem: (problem) => problems.push(problem),
    })
    await tailwind.refresh()
    const good = tailwind.current()
    expect(good?.css).toContain('.bg-brand')
    writeFileSync(
      join(root, 'css', 'tailwind.css'),
      '@import "tailwindcss";\n\n@theme {\n  --x: 1;\n',
    )
    await tailwind.refresh()
    expect(problems).toEqual([
      { file: 'css/tailwind.css', line: 3, message: expect.stringContaining('Missing closing }') },
    ])
    expect(tailwind.current()).toBe(good as NonNullable<typeof good>)
    // Said once, not on every rebuild while it stays broken.
    await tailwind.refresh()
    expect(problems.length).toBe(1)
    writeFileSync(join(root, 'css', 'tailwind.css'), INPUT)
    await tailwind.refresh()
    expect(tailwind.problem()).toBeUndefined()
  })

  test('an unknown class in @apply is found by name, for its line', () => {
    const css = '@import "tailwindcss";\n.card {\n  @apply p-4 nope;\n}\n'
    expect(
      tailwindProblem(new Error('Cannot apply unknown utility class `nope`'), { css }, '/site'),
    ).toMatchObject({ line: 3 })
  })

  test('that does not compile is a problem `install` reports', async () => {
    const { config } = siteFiles({ input: '@theme {\n' })
    const problems = await buildAhead(loadConfig(config))
    expect(problems.some((problem) => problem.startsWith('The Tailwind stylesheet:'))).toBe(true)
  })
})

describe('styles.tailwind: false', () => {
  test('generates and links nothing, and the editor is offered no classes', async () => {
    const { h, visit } = await site({ config: { styles: { tailwind: false } } })
    const html = await (await visit('/')).text()
    expect(html).not.toContain('/css/tailwind.')
    expect((await visit(TAILWIND_PATH)).status).toBe(404)
    const list = await h.json<TailwindClassList>(CLASSES)
    expect(list).toMatchObject({ enabled: false, classes: [], variants: [] })
  })

  test('is CROMBOLO_STYLES_TAILWIND=false too, and on by default', () => {
    const previous = Bun.env.CROMBOLO_STYLES_TAILWIND
    try {
      expect(loadConfig({}).styles.tailwind).toBe(true)
      Bun.env.CROMBOLO_STYLES_TAILWIND = 'false'
      expect(loadConfig({}).styles.tailwind).toBe(false)
      expect(loadConfig({ styles: { tailwind: true } }).styles.tailwind).toBe(true)
    } finally {
      if (previous === undefined) delete Bun.env.CROMBOLO_STYLES_TAILWIND
      else Bun.env.CROMBOLO_STYLES_TAILWIND = previous
    }
  })
})

describe('the link', () => {
  const href = '/css/tailwind.0123abcd.css'
  const tag = `<link rel="stylesheet" href="${href}">`

  test('goes before the first stylesheet in the head', () => {
    expect(
      withPageStylesheet(
        '<html><head><meta charset="utf-8"><style>a{}</style><link rel="stylesheet" href="/css/site.css"></head></html>',
        href,
      ),
    ).toBe(
      `<html><head><meta charset="utf-8">${tag}<style>a{}</style><link rel="stylesheet" href="/css/site.css"></head></html>`,
    )
  })

  test('goes at the end of a head with no stylesheet', () => {
    expect(withPageStylesheet('<head><title>x</title></head><body></body>', href)).toBe(
      `<head><title>x</title>${tag}</head><body></body>`,
    )
  })

  test('is not added where the page links it, or has no head', () => {
    const own = '<head><link rel="stylesheet" href="/css/tailwind.css"></head>'
    expect(withPageStylesheet(own, href)).toBe(own)
    expect(withPageStylesheet('<p>a part</p>', href)).toBe('<p>a part</p>')
  })
})

describe('the class list the template editor completes from', () => {
  test('is every class with its CSS and colour, the site’s @theme included, and the variants', async () => {
    const { h } = await site({ input: '@import "tailwindcss";\n@theme { --color-brand: #f60; }\n' })
    const list = await h.json<TailwindClassList>(CLASSES)
    expect(list.enabled).toBe(true)
    const byName = new Map(list.classes.map((entry) => [entry[0], entry]))
    expect(byName.get('p-4')?.[1]).toContain('padding: calc(var(--spacing) * 4)')
    expect(byName.get('bg-red-500')?.[2]).toBe('#fb2c36')
    expect(byName.get('bg-brand')?.[2]).toBe('#ff6600')
    expect(byName.get('p-4')?.[2]).toBeUndefined()
    for (const variant of ['hover', 'focus', 'md', 'dark', 'group-hover'])
      expect(list.variants).toContain(variant)
  })

  test('is tagged and gzipped, and asked only by someone signed in', async () => {
    const { h, visit } = await site()
    const first = await h.server.fetch(
      new Request(`${ORIGIN}${CLASSES}`, {
        headers: { cookie: h.cookie(), 'accept-encoding': 'gzip' },
      }),
    )
    expect(first.headers.get('content-encoding')).toBe('gzip')
    const etag = first.headers.get('etag') as string
    const again = await h.server.fetch(
      new Request(`${ORIGIN}${CLASSES}`, {
        headers: { cookie: h.cookie(), 'if-none-match': etag },
      }),
    )
    expect(again.status).toBe(304)
    expect((await visit(CLASSES)).status).toBe(401)
  })
})

describe('colours', () => {
  test('are drawn as hex from Tailwind’s oklch, rgb and hex', () => {
    expect(cssColorToHex('oklch(63.7% 0.237 25.331)')).toBe('#fb2c36')
    expect(cssColorToHex('oklch(100% 0 0)')).toBe('#ffffff')
    expect(cssColorToHex('#f60')).toBe('#ff6600')
    expect(cssColorToHex('rgb(255 0 0)')).toBe('#ff0000')
    expect(cssColorToHex('currentcolor')).toBeUndefined()
  })
})

describe('a new site', () => {
  test('has css/tailwind.css, so Tailwind’s own editor extension switches on', () => {
    const file = scaffoldFiles().find((entry) => entry.path === 'css/tailwind.css')
    expect(file?.text).toBe('@import "tailwindcss";\n')
  })

  test('styles its template with Tailwind’s classes', () => {
    const template = readFileSync(
      'packages/cli/templates/basic/files/components/contentPage.tsx',
      'utf8',
    )
    expect(template).toContain('className="')
    expect(template).not.toContain('<style>')
  })
})
